create table if not exists public.clinical_encounter_trace_references (id uuid primary key default gen_random_uuid(),source_trace_id uuid not null references public.clinical_reasoning_traces(id) on delete restrict,case_id text not null,case_version text not null,reference_role text not null check(reference_role in('author_reference_trace','expert_benchmark')),designated_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now(),unique(source_trace_id,reference_role));
alter table public.clinical_encounter_trace_references enable row level security;
create policy "clinical_encounter_trace_references_admin_only" on public.clinical_encounter_trace_references for all to authenticated using(exists(select 1 from public.bty_platform_admin_grants g where g.user_id=auth.uid() and g.status='active')) with check(exists(select 1 from public.bty_platform_admin_grants g where g.user_id=auth.uid() and g.status='active'));
